const tasks=[['start','Find the start and describe what the guide will help with.'],['lifestyle','Choose an Austin lifestyle and explain the final income range.'],['profile','Answer activity and experience questions; go back, pause and resume.'],['pathways','Explain the six interest scores and compare the suggested pathways.'],['other-field','Find another field without treating it as a forced match.'],['profession','Compare duties, education and preparation for two professions.'],['money','Distinguish training pay, qualified entry pay and modeled later pay. Try a loan or work-hours scenario.'],['plan','Find the next activity, record a note and mark it completed.'],['switch','Change career and confirm earlier notes and completed work remain.'],['return','Reload the guide, find the saved plan and identify one next action.']];
const key='fieldguide-usability-sessions-031',form=document.querySelector('form'),msg=document.querySelector('#message');let rows=[];try{rows=JSON.parse(localStorage.getItem(key)||'[]');if(!Array.isArray(rows))rows=[];}catch{msg.textContent='Browser records could not be loaded. Export any visible work before leaving.';}
const esc=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
document.querySelector('#tasks').innerHTML=tasks.map(([id,text])=>`<section class="task"><strong>${text}</strong><label>Observed result<select name="task-${id}"><option value="">Not observed</option><option>Completed without help</option><option>Completed with a prompt</option><option>Could not complete</option><option>Skipped by student</option></select></label><label>Observation<textarea name="note-${id}" maxlength="2000"></textarea></label></section>`).join('');
function show(){document.querySelector('#count').textContent=rows.length?rows.length+' observed session'+(rows.length===1?'':'s')+' recorded on this browser.':'No sessions recorded on this browser.';document.querySelector('#sessions').innerHTML=rows.map(r=>'<li>'+esc(r.participant)+' · '+esc(r.date)+' · '+esc(r.relevance||'Review incomplete')+'</li>').join('');}
function fresh(){form.reset();form.elements.date.value=new Date().toLocaleDateString('en-CA');}fresh();show();
form.addEventListener('submit',e=>{e.preventDefault();const entry=Object.fromEntries(new FormData(form));entry.recordedAt=new Date().toISOString();entry.release='0.31.0';const next=[...rows,entry];try{localStorage.setItem(key,JSON.stringify(next));rows=next;show();msg.textContent='Session saved on this browser. Start another when ready.';}catch{msg.textContent='Storage is unavailable. Export the sessions before leaving.';}});
document.querySelector('#new-session').addEventListener('click',()=>{fresh();msg.textContent='New session ready. Earlier records remain.';});document.querySelector('#export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({application:'Fieldguide',purpose:'Observed usability sessions; not psychometric validation',exportedAt:new Date().toISOString(),sessions:rows},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fieldguide-usability-sessions.json';a.click();URL.revokeObjectURL(url);});
